-- The cases of test_run_sql_subquery: each COPY line below is one case, the
-- query DuckDB runs over the tables of data.sql (t, u, nn and e, each a
-- `.parquet` file) and the file its answer goes to. The test reads THIS FILE
-- for the query text and runs the same text through run_sql with each file
-- name replaced by its path, so a query has one source. A case's name is its
-- output file without `.tsv`.
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v = (SELECT max(u.v) - 85 FROM read_parquet('u.parquet') u)) TO 'scalar_eq_max.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE (SELECT min(u.v) FROM read_parquet('u.parquet') u) + 100 < t.v) TO 'scalar_left_operand.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_avg_double.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v * 10 >= (SELECT sum(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_sum.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.d AS d FROM read_parquet('t.parquet') t WHERE t.d = (SELECT max(u.d) FROM read_parquet('u.parquet') u)) TO 'scalar_decimal_eq.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.d AS d FROM read_parquet('t.parquet') t WHERE t.d < (SELECT max(u.d) FROM read_parquet('u.parquet') u WHERE u.k = 4)) TO 'scalar_decimal_lt.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.dt AS dt FROM read_parquet('t.parquet') t WHERE t.dt >= (SELECT min(u.dt) FROM read_parquet('u.parquet') u)) TO 'scalar_date.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.g AS g FROM read_parquet('t.parquet') t WHERE t.g < (SELECT count(*) FROM read_parquet('nn.parquet') nn)) TO 'scalar_int32_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT max(e.v) FROM read_parquet('e.parquet') e)) TO 'scalar_empty_max.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT count(*) FROM read_parquet('e.parquet') e)) TO 'scalar_empty_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE (SELECT max(e.v) FROM read_parquet('e.parquet') e) IS NULL) TO 'scalar_empty_is_null.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT min(u.v) FROM read_parquet('u.parquet') u) AND t.v < (SELECT max(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_two_bounds.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k > 1 AND t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_and_chain.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k = 0 OR t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_or.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v < (SELECT max(u.v) FROM read_parquet('u.parquet') u WHERE u.k = 4)) TO 'scalar_filtered_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u WHERE u.v < (SELECT max(t2.v) FROM read_parquet('t.parquet') t2))) TO 'scalar_nested.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n FROM read_parquet('t.parquet') t WHERE t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_count_star_where.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT u.v FROM read_parquet('u.parquet') u WHERE u.id = 3 LIMIT 1)) TO 'scalar_limit_one_row.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, (SELECT u.v FROM read_parquet('u.parquet') u WHERE u.id < 0 LIMIT 1) AS m FROM read_parquet('t.parquet') t) TO 'scalar_limit_no_row_select.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE (SELECT u.v FROM read_parquet('u.parquet') u WHERE u.id < 0 LIMIT 1) IS NULL) TO 'scalar_limit_no_row_is_null.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, (SELECT u.dt FROM read_parquet('u.parquet') u WHERE u.id = 2 LIMIT 1) AS m FROM read_parquet('t.parquet') t) TO 'scalar_limit_date_select.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.d AS d FROM read_parquet('t.parquet') t WHERE (SELECT u.d FROM read_parquet('u.parquet') u WHERE u.id < 0 LIMIT 1) IS NULL AND t.d > 3) TO 'scalar_limit_decimal_no_row.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, (SELECT max(u.v) FROM read_parquet('u.parquet') u) AS m FROM read_parquet('t.parquet') t) TO 'scalar_select_item.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.v - (SELECT min(u.v) FROM read_parquet('u.parquet') u) AS dv FROM read_parquet('t.parquet') t) TO 'scalar_select_expr.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, (SELECT max(e.v) FROM read_parquet('e.parquet') e) AS m FROM read_parquet('t.parquet') t) TO 'scalar_select_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT (SELECT max(u.v) FROM read_parquet('u.parquet') u) AS m) TO 'scalar_select_no_from.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, CASE WHEN t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u) THEN 1 ELSE 0 END AS hi FROM read_parquet('t.parquet') t) TO 'scalar_select_case.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, coalesce((SELECT max(e.v) FROM read_parquet('e.parquet') e), -1) AS m FROM read_parquet('t.parquet') t) TO 'scalar_select_coalesce.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.g AS g, count(*) AS n, (SELECT max(u.v) FROM read_parquet('u.parquet') u) AS m FROM read_parquet('t.parquet') t GROUP BY t.g) TO 'scalar_grouped_select.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT sum(t.v) + (SELECT max(u.v) FROM read_parquet('u.parquet') u) AS x FROM read_parquet('t.parquet') t) TO 'scalar_agg_plus.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.g AS g, sum(t.v) AS sv FROM read_parquet('t.parquet') t GROUP BY t.g HAVING sum(t.v) * 4 > (SELECT sum(u.v) FROM read_parquet('u.parquet') u)) TO 'scalar_having.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.k AS k, sum(t.d) AS sd FROM read_parquet('t.parquet') t GROUP BY t.k HAVING sum(t.d) * 5 > (SELECT sum(u.d) FROM read_parquet('u.parquet') u)) TO 'scalar_having_decimal.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (WITH rev AS (SELECT t.g AS g, sum(t.d) AS total FROM read_parquet('t.parquet') t GROUP BY t.g) SELECT rev.g AS g, rev.total AS total FROM rev WHERE rev.total = (SELECT max(r2.total) FROM rev r2)) TO 'scalar_cte_max.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > (SELECT avg(x.sv) FROM (SELECT u.k AS k, sum(u.v) AS sv FROM read_parquet('u.parquet') u GROUP BY u.k) x)) TO 'scalar_derived_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u)) TO 'in_with_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.g AS g FROM read_parquet('t.parquet') t WHERE t.g IN (SELECT u.g FROM read_parquet('u.parquet') u)) TO 'in_int32.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.g AS g FROM read_parquet('t.parquet') t WHERE t.g IN (SELECT u.k FROM read_parquet('u.parquet') u)) TO 'in_int32_int64.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.s AS s FROM read_parquet('t.parquet') t WHERE t.s IN (SELECT u.s FROM read_parquet('u.parquet') u)) TO 'in_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT DISTINCT u.k FROM read_parquet('u.parquet') u)) TO 'in_distinct.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u GROUP BY u.k HAVING sum(u.v) > 300)) TO 'in_group_having.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u, read_parquet('nn.parquet') nn WHERE u.k = nn.k AND nn.g = 0)) TO 'in_join_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k - 2 FROM read_parquet('u.parquet') u)) TO 'in_expr_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u WHERE u.id < 6 LIMIT 100)) TO 'in_limit_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v IN (SELECT min(u.v) + 50 FROM read_parquet('u.parquet') u)) TO 'in_agg_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT e.k FROM read_parquet('e.parquet') e)) TO 'in_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u) AND t.g IN (SELECT nn.g FROM read_parquet('nn.parquet') nn)) TO 'in_two.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u) AND t.v > (SELECT avg(u.v) FROM read_parquet('u.parquet') u)) TO 'in_and_scalar.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n, count(t.k) AS nk FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u)) TO 'in_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.g AS g, count(*) AS n FROM read_parquet('t.parquet') t WHERE t.k IN (SELECT u.k FROM read_parquet('u.parquet') u) GROUP BY t.g) TO 'in_grouped_after.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k FROM read_parquet('u.parquet') u)) TO 'not_in_with_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT nn.k FROM read_parquet('nn.parquet') nn)) TO 'not_in_null_free.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT e.k FROM read_parquet('e.parquet') e)) TO 'not_in_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.g AS g FROM read_parquet('t.parquet') t WHERE t.g NOT IN (SELECT nn.g FROM read_parquet('nn.parquet') nn)) TO 'not_in_int32.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.g AS g FROM read_parquet('t.parquet') t WHERE t.g NOT IN (SELECT u.g FROM read_parquet('u.parquet') u)) TO 'not_in_int32_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.s AS s FROM read_parquet('t.parquet') t WHERE t.s NOT IN (SELECT u.s FROM read_parquet('u.parquet') u WHERE u.s LIKE 's%')) TO 'not_in_string.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT DISTINCT u.k FROM read_parquet('u.parquet') u)) TO 'not_in_distinct_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT DISTINCT nn.k FROM read_parquet('nn.parquet') nn)) TO 'not_in_distinct_null_free.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k FROM read_parquet('u.parquet') u GROUP BY u.k HAVING count(*) < 4)) TO 'not_in_group_having_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k FROM read_parquet('u.parquet') u WHERE u.k IS NOT NULL GROUP BY u.k HAVING count(*) > 3)) TO 'not_in_group_having_null_free.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k FROM read_parquet('u.parquet') u GROUP BY u.k HAVING count(*) > 100)) TO 'not_in_group_empty.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k FROM read_parquet('u.parquet') u WHERE u.id < 6 LIMIT 100)) TO 'not_in_limit_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT u.k - 2 FROM read_parquet('u.parquet') u)) TO 'not_in_expr_body_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT nn.k - 2 FROM read_parquet('nn.parquet') nn)) TO 'not_in_expr_body_null_free.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.v > 50 AND t.k NOT IN (SELECT nn.k FROM read_parquet('nn.parquet') nn)) TO 'not_in_and_filter.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n FROM read_parquet('t.parquet') t WHERE t.k NOT IN (SELECT nn.k FROM read_parquet('nn.parquet') nn WHERE nn.k > 4)) TO 'not_in_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k IN (1, 2, NULL)) TO 'in_list_null.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (1, 2)) TO 'not_in_list.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.k AS k, t.v AS v FROM read_parquet('t.parquet') t WHERE t.k NOT IN (1, NULL)) TO 'not_in_list_null.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
